package api

import (
	"encoding/hex"
	"encoding/json"
	"errors"
	"net/http"
	"strconv"
	"strings"

	"github.com/go-chi/chi/v5"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"retropick/apps/backend/internal/dbqueries"
	"retropick/apps/backend/internal/ethops"
	"retropick/apps/backend/internal/registry"
)

const opsListLimitDefault = 100

// OpsRouter returns chi.Router mounted at /api/v1/ops (no prefix inside).
// eth may be nil to disable live RPC routes (indexed routes still work).
func OpsRouter(pool *pgxpool.Pool, reg *registry.Registry, eth *ethops.Caller) chi.Router {
	r := chi.NewRouter()
	q := dbqueries.New(pool)

	r.Get("/global-state", func(w http.ResponseWriter, r *http.Request) {
		ctx := r.Context()
		st, err := q.GetIndexerState(ctx)
		if err != nil {
			http.Error(w, `{"error":"db"}`, http.StatusInternalServerError)
			return
		}
		nTemplates, _ := q.CountTemplates(ctx)
		nHalted, _ := q.CountTemplatesRollingHalted(ctx)
		nOpenIncidents, _ := q.CountOpenIncidents(ctx)

		var lastHash *string
		if st.LastBlockHash.Valid {
			s := st.LastBlockHash.String
			lastHash = &s
		}
		var lastSync *string
		if st.LastIndexedAt.Valid {
			s := st.LastIndexedAt.Time.UTC().Format("2006-01-02T15:04:05Z07:00")
			lastSync = &s
		}

		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{
			"source": "indexed",
			"environment": map[string]any{
				"name":    reg.Environment,
				"chainId": reg.ChainID,
			},
			"contracts": map[string]any{
				"marketEngineProxy": reg.Contracts.MarketEngineProxy,
			},
			"indexer": map[string]any{
				"lastIndexedBlock": st.LastBlock,
				"lastBlockHash":    lastHash,
				"lastSyncAt":       lastSync,
				"reorgDepth":       st.ReorgDepth,
			},
			"counts": map[string]any{
				"templates":     nTemplates,
				"rollingHalted": nHalted,
				"openIncidents": nOpenIncidents,
			},
			"liveProtocolFields": nil,
			"liveFieldsNote":     "On-chain fields (globalPaused, yieldRouterDisabled, etc.) require explicit live RPC reads; not included in this indexed response.",
		})
	})

	r.Get("/templates", func(w http.ResponseWriter, r *http.Request) {
		ctx := r.Context()
		rows, err := q.ListTemplatesWithLedger(ctx)
		if err != nil {
			http.Error(w, `{"error":"db"}`, http.StatusInternalServerError)
			return
		}
		st, _ := q.GetIndexerState(ctx)
		out := make([]map[string]any, 0, len(rows))
		for _, row := range rows {
			m := map[string]any{
				"templateId":        "0x" + hex.EncodeToString(row.TemplateID),
				"slug":              row.Slug,
				"marketType":        row.MarketType,
				"outcomeCount":      row.OutcomeCount,
				"initialized":       row.Initialized,
				"executionMode":     row.ExecutionMode,
				"rollingPhase":      row.RollingPhase,
				"rollingHaltReason": row.RollingHaltReason,
				"published":         row.Initialized && row.ActiveEpochID.Valid,
				"lastIndexedBlock":  st.LastBlock,
				"templateUpdatedAt": formatTS(row.UpdatedAt),
			}
			if row.ActiveEpochID.Valid {
				m["activeEpochId"] = row.ActiveEpochID.Int64
			}
			if row.LastResolvedEpochID.Valid {
				m["lastResolvedEpochId"] = row.LastResolvedEpochID.Int64
			}
			if row.RollingNextEpochID.Valid {
				m["rollingNextEpochId"] = row.RollingNextEpochID.Int64
			}
			if row.HaltedAtEpochID.Valid {
				m["haltedAtEpochId"] = row.HaltedAtEpochID.Int64
			}
			out = append(out, m)
		}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{"templates": out, "source": "indexed"})
	})

	r.Get("/templates/{templateId}/state", func(w http.ResponseWriter, r *http.Request) {
		ctx := r.Context()
		b, ok := parseTemplateIDParam(chi.URLParam(r, "templateId"))
		if !ok {
			http.Error(w, `{"error":"invalid templateId"}`, http.StatusBadRequest)
			return
		}
		row, err := q.GetTemplateLedgerDetail(ctx, b)
		if err != nil {
			if errors.Is(err, pgx.ErrNoRows) {
				http.Error(w, `{"error":"not found"}`, http.StatusNotFound)
				return
			}
			http.Error(w, `{"error":"db"}`, http.StatusInternalServerError)
			return
		}
		st, _ := q.GetIndexerState(ctx)
		resp := map[string]any{
			"source":                 "indexed",
			"templateId":             "0x" + hex.EncodeToString(row.TemplateID),
			"slug":                   row.Slug,
			"marketType":             row.MarketType,
			"outcomeCount":           row.OutcomeCount,
			"oracleMaxDelaySeconds":  row.OracleMaxDelaySeconds,
			"oracleMaxConfidenceBps": row.OracleMaxConfidenceBps,
			"initialized":            row.Initialized,
			"executionMode":          row.ExecutionMode,
			"rollingPhase":           row.RollingPhase,
			"rollingHaltReason":      row.RollingHaltReason,
			"templateUpdatedAt":      formatTS(row.UpdatedAt),
			"lastIndexedBlock":       st.LastBlock,
		}
		if row.ActiveEpochID.Valid {
			resp["activeEpochId"] = row.ActiveEpochID.Int64
		}
		if row.LastResolvedEpochID.Valid {
			resp["lastResolvedEpochId"] = row.LastResolvedEpochID.Int64
		}
		if row.RollingNextEpochID.Valid {
			resp["rollingNextEpochId"] = row.RollingNextEpochID.Int64
		}
		if row.HaltedAtEpochID.Valid {
			resp["haltedAtEpochId"] = row.HaltedAtEpochID.Int64
		}
		resp["ledgerUpdatedAt"] = formatTS(row.LedgerUpdatedAt)
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(resp)
	})

	r.Get("/templates/{templateId}/epochs/{epochId}", func(w http.ResponseWriter, r *http.Request) {
		ctx := r.Context()
		b, ok := parseTemplateIDParam(chi.URLParam(r, "templateId"))
		if !ok {
			http.Error(w, `{"error":"invalid templateId"}`, http.StatusBadRequest)
			return
		}
		epochID, err := strconv.ParseInt(chi.URLParam(r, "epochId"), 10, 64)
		if err != nil || epochID < 0 {
			http.Error(w, `{"error":"invalid epochId"}`, http.StatusBadRequest)
			return
		}
		e, err := q.GetEpoch(ctx, dbqueries.GetEpochParams{TemplateID: b, EpochID: epochID})
		if err != nil {
			if errors.Is(err, pgx.ErrNoRows) {
				http.Error(w, `{"error":"not found"}`, http.StatusNotFound)
				return
			}
			http.Error(w, `{"error":"db"}`, http.StatusInternalServerError)
			return
		}
		st, _ := q.GetIndexerState(ctx)
		resp := map[string]any{
			"source":           "indexed",
			"templateId":       "0x" + hex.EncodeToString(e.TemplateID),
			"epochId":          e.EpochID,
			"status":           e.Status,
			"openAt":           formatTS(e.OpenAt),
			"lockAt":           formatTS(e.LockAt),
			"resolveAt":        formatTS(e.ResolveAt),
			"openTxHash":       nullText(e.OpenTxHash),
			"lockTxHash":       nullText(e.LockTxHash),
			"resolveTxHash":    nullText(e.ResolveTxHash),
			"claimable":        e.Claimable,
			"refMode":          e.RefMode,
			"updatedAt":        formatTS(e.UpdatedAt),
			"lastIndexedBlock": st.LastBlock,
		}
		if e.WinningOutcomeMask.Valid {
			resp["winningOutcomeMask"] = e.WinningOutcomeMask.Int32
		}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(resp)
	})

	r.Get("/keeper/schedule", func(w http.ResponseWriter, r *http.Request) {
		limit := opsLimit(r.URL.Query().Get("limit"))
		rows, err := q.ListKeeperSchedule(r.Context(), limit)
		if err != nil {
			http.Error(w, `{"error":"db"}`, http.StatusInternalServerError)
			return
		}
		out := make([]map[string]any, 0, len(rows))
		for _, row := range rows {
			m := map[string]any{
				"id":     row.ID,
				"action": row.Action,
				"status": row.Status,
			}
			if row.ScheduledAt.Valid {
				m["scheduledAt"] = row.ScheduledAt.Time.UTC().Format("2006-01-02T15:04:05Z07:00")
			}
			if row.WindowEndAt.Valid {
				m["windowEndAt"] = row.WindowEndAt.Time.UTC().Format("2006-01-02T15:04:05Z07:00")
			}
			if row.CreatedAt.Valid {
				m["createdAt"] = row.CreatedAt.Time.UTC().Format("2006-01-02T15:04:05Z07:00")
			}
			if len(row.TemplateID) > 0 {
				m["templateId"] = "0x" + hex.EncodeToString(row.TemplateID)
			}
			if row.EpochID.Valid {
				m["epochId"] = row.EpochID.Int64
			}
			out = append(out, m)
		}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{"schedule": out, "source": "indexed"})
	})

	r.Get("/keeper/executions", func(w http.ResponseWriter, r *http.Request) {
		limit := opsLimit(r.URL.Query().Get("limit"))
		rows, err := q.ListKeeperExecutions(r.Context(), limit)
		if err != nil {
			http.Error(w, `{"error":"db"}`, http.StatusInternalServerError)
			return
		}
		out := make([]map[string]any, 0, len(rows))
		for _, row := range rows {
			m := map[string]any{
				"id":     row.ID,
				"action": row.Action,
				"result": row.Result,
			}
			if row.ExecutedAt.Valid {
				m["executedAt"] = row.ExecutedAt.Time.UTC().Format("2006-01-02T15:04:05Z07:00")
			}
			if len(row.TemplateID) > 0 {
				m["templateId"] = "0x" + hex.EncodeToString(row.TemplateID)
			}
			if row.EpochID.Valid {
				m["epochId"] = row.EpochID.Int64
			}
			if row.TxHash.Valid {
				m["txHash"] = row.TxHash.String
			}
			if row.ErrorMessage.Valid {
				m["errorMessage"] = row.ErrorMessage.String
			}
			out = append(out, m)
		}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{"executions": out, "source": "indexed"})
	})

	r.Get("/incidents", func(w http.ResponseWriter, r *http.Request) {
		limit := opsLimit(r.URL.Query().Get("limit"))
		rows, err := q.ListIncidents(r.Context(), limit)
		if err != nil {
			http.Error(w, `{"error":"db"}`, http.StatusInternalServerError)
			return
		}
		out := make([]map[string]any, 0, len(rows))
		for _, row := range rows {
			m := map[string]any{
				"id":       row.ID,
				"title":    row.Title,
				"severity": row.Severity,
				"status":   row.Status,
				"payload":  json.RawMessage(row.Payload),
			}
			if row.OpenedAt.Valid {
				m["openedAt"] = row.OpenedAt.Time.UTC().Format("2006-01-02T15:04:05Z07:00")
			}
			if len(row.TemplateID) > 0 {
				m["templateId"] = "0x" + hex.EncodeToString(row.TemplateID)
			}
			out = append(out, m)
		}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{"incidents": out, "source": "indexed"})
	})

	r.Get("/oracle/health", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{
			"feeds":  []any{},
			"note":   "oracle_health table not migrated; no feed projections yet.",
			"source": "stub",
		})
	})

	r.Get("/audit", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{"events": []any{}, "source": "stub"})
	})

	registerOpsFeedRoutes(r, reg)
	registerOpsLiveRoutes(r, eth, reg)
	registerOpsPrepareRoutes(r, eth, reg)
	registerOpsFrontendVisibilityRoutes(r, pool)

	return r
}

func parseTemplateIDParam(raw string) ([]byte, bool) {
	s := strings.TrimPrefix(strings.TrimSpace(raw), "0x")
	b, err := hex.DecodeString(s)
	if err != nil || len(b) != 32 {
		return nil, false
	}
	return b, true
}

func opsLimit(s string) int32 {
	if s == "" {
		return opsListLimitDefault
	}
	n, err := strconv.Atoi(s)
	if err != nil || n < 1 || n > 500 {
		return opsListLimitDefault
	}
	return int32(n)
}

func formatTS(t pgtype.Timestamptz) any {
	if !t.Valid {
		return nil
	}
	return t.Time.UTC().Format("2006-01-02T15:04:05Z07:00")
}

func nullText(t pgtype.Text) any {
	if !t.Valid {
		return nil
	}
	return t.String
}

files.apps/backend/internal/api/rpc_timeout.go:
package api

import (
	"context"
	"net/http"
	"os"
	"strconv"
	"strings"
	"time"
)

func liveRPCContext(req *http.Request) (context.Context, context.CancelFunc) {
	timeout := 15 * time.Second
	if raw := strings.TrimSpace(os.Getenv("LIVE_RPC_TIMEOUT")); raw != "" {
		if d, err := time.ParseDuration(raw); err == nil && d > 0 {
			timeout = d
		} else if seconds, err := strconv.Atoi(raw); err == nil && seconds > 0 {
			timeout = time.Duration(seconds) * time.Second
		}
	} else if raw := strings.TrimSpace(os.Getenv("LIVE_RPC_TIMEOUT_SECONDS")); raw != "" {
		if seconds, err := strconv.Atoi(raw); err == nil && seconds > 0 {
			timeout = time.Duration(seconds) * time.Second
		}
	}
	return context.WithTimeout(req.Context(), timeout)
}

files.apps/backend/internal/api/user_public.go:
package api

import (
	"encoding/hex"
	"encoding/json"
	"net/http"
	"strconv"
	"strings"
	"time"

	"github.com/ethereum/go-ethereum/common"
	"github.com/jackc/pgx/v5/pgxpool"

	"retropick/apps/backend/internal/dbqueries"
	"retropick/apps/backend/internal/ethops"
	"retropick/apps/backend/internal/registry"
)

const userPositionsMaxPairs = 48

type userTemplateEpochPair struct {
	templateID []byte
	epochID    int64
	source     string
}

func requestedTemplateEpochPair(r *http.Request) (*userTemplateEpochPair, bool) {
	templateIDRaw := strings.TrimPrefix(strings.TrimSpace(r.URL.Query().Get("templateId")), "0x")
	epochIDRaw := strings.TrimSpace(r.URL.Query().Get("epochId"))
	if templateIDRaw == "" && epochIDRaw == "" {
		return nil, true
	}
	if templateIDRaw == "" || epochIDRaw == "" {
		return nil, false
	}
	tid, err := hex.DecodeString(templateIDRaw)
	if err != nil || len(tid) != 32 {
		return nil, false
	}
	epochID, err := strconv.ParseInt(epochIDRaw, 10, 64)
	if err != nil || epochID < 0 {
		return nil, false
	}
	return &userTemplateEpochPair{templateID: tid, epochID: epochID, source: "rpc+requested_pair"}, true
}

func pairKey(templateID []byte, epochID int64) string {
	return hex.EncodeToString(templateID) + ":" + strconv.FormatInt(epochID, 10)
}

// UserPositionsHandler returns live position views for (template, epoch) pairs the user touched (indexed).
func UserPositionsHandler(pool *pgxpool.Pool, eth *ethops.Caller, reg *registry.Registry) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		wallet := strings.TrimSpace(r.URL.Query().Get("wallet"))
		if !strings.HasPrefix(wallet, "0x") || len(wallet) != 42 {
			http.Error(w, `{"error":"invalid wallet (use ?wallet=0x...)"}`, http.StatusBadRequest)
			return
		}
		requestedPair, ok := requestedTemplateEpochPair(r)
		if !ok {
			http.Error(w, `{"error":"invalid templateId/epochId"}`, http.StatusBadRequest)
			return
		}
		q := dbqueries.New(pool)
		st, err := q.GetIndexerState(r.Context())
		if err != nil {
			http.Error(w, `{"error":"db"}`, http.StatusInternalServerError)
			return
		}
		var lastSync *string
		if st.LastIndexedAt.Valid {
			s := st.LastIndexedAt.Time.UTC().Format(time.RFC3339)
			lastSync = &s
		}
		pairLimit := int32(userPositionsMaxPairs)
		rows, err := q.ListUserTemplateEpochPairs(r.Context(), dbqueries.ListUserTemplateEpochPairsParams{
			UserAddress: wallet,
			Limit:       pairLimit,
		})
		if err != nil {
			http.Error(w, `{"error":"db"}`, http.StatusInternalServerError)
			return
		}

		pairs := make([]userTemplateEpochPair, 0, len(rows)+1)
		seen := make(map[string]struct{}, len(rows)+1)
		for _, row := range rows {
			if len(row.TemplateID) != 32 {
				continue
			}
			seen[pairKey(row.TemplateID, row.EpochID)] = struct{}{}
			pairs = append(pairs, userTemplateEpochPair{
				templateID: row.TemplateID,
				epochID:    row.EpochID,
				source:     "rpc+indexed_keys",
			})
		}
		if requestedPair != nil {
			key := pairKey(requestedPair.templateID, requestedPair.epochID)
			if _, exists := seen[key]; !exists {
				pairs = append([]userTemplateEpochPair{*requestedPair}, pairs...)
			}
		}

		positions := make([]map[string]any, 0, len(pairs))
		if eth != nil {
			proxy := common.HexToAddress(reg.Contracts.MarketEngineProxy)
			user := common.HexToAddress(wallet)
			for _, pair := range pairs {
				tid := common.BytesToHash(pair.templateID)
				rpcCtx, cancel := liveRPCContext(r)
				pv, blockNum, err := eth.GetPositionView(rpcCtx, proxy, tid, uint64(pair.epochID), user)
				cancel()
				if err != nil {
					positions = append(positions, map[string]any{
						"templateId": "0x" + hex.EncodeToString(pair.templateID),
						"epochId":    pair.epochID,
						"error":      err.Error(),
					})
					continue
				}
				m, ok := ethops.ToJSONMap(pv).(map[string]any)
				if !ok {
					m = map[string]any{}
				}
				m["templateId"] = "0x" + hex.EncodeToString(pair.templateID)
				m["epochId"] = pair.epochID
				m["wallet"] = strings.ToLower(wallet)
				m["positionViewBlock"] = blockNum
				m["source"] = pair.source
				positions = append(positions, m)
			}
		}

		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{
			"wallet":    strings.ToLower(wallet),
			"positions": positions,
			"dataFreshness": map[string]any{
				"lastSyncAt":       lastSync,
				"lastIndexedBlock": st.LastBlock,
			},
		})
	}
}

// UserClaimsHandler lists Claimed events with indexer payload and epoch claim flags.
func UserClaimsHandler(pool *pgxpool.Pool) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		wallet := strings.TrimSpace(r.URL.Query().Get("wallet"))
		if !strings.HasPrefix(wallet, "0x") || len(wallet) != 42 {
			http.Error(w, `{"error":"invalid wallet"}`, http.StatusBadRequest)
			return
		}
		limit := int32(100)
		if ls := r.URL.Query().Get("limit"); ls != "" {
			if n, err := strconv.ParseInt(ls, 10, 32); err == nil && n > 0 && n <= 500 {
				limit = int32(n)
			}
		}
		q := dbqueries.New(pool)
		st, err := q.GetIndexerState(r.Context())
		if err != nil {
			http.Error(w, `{"error":"db"}`, http.StatusInternalServerError)
			return
		}
		var lastSync *string
		if st.LastIndexedAt.Valid {
			s := st.LastIndexedAt.Time.UTC().Format(time.RFC3339)
			lastSync = &s
		}
		rows, err := q.ListUserClaimedEvents(r.Context(), dbqueries.ListUserClaimedEventsParams{
			UserAddress: wallet,
			Limit:       limit,
		})
		if err != nil {
			http.Error(w, `{"error":"db"}`, http.StatusInternalServerError)
			return
		}
		claims := make([]map[string]any, 0, len(rows))
		for _, row := range rows {
			var payload map[string]any
			_ = json.Unmarshal(row.Payload, &payload)
			tplHex := "0x" + hex.EncodeToString(row.TemplateID)
			claimM := map[string]any{
				"id":          row.ID,
				"templateId":  tplHex,
				"epochId":     row.EpochID,
				"txHash":      row.TxHash,
				"blockNumber": row.BlockNumber,
			}
			if row.IndexedAt.Valid {
				claimM["indexedAt"] = row.IndexedAt.Time.UTC().Format(time.RFC3339)
			}
			if payload != nil {
				claimM["eventPayload"] = payload
			}
			ep, err := q.GetEpoch(r.Context(), dbqueries.GetEpochParams{
				TemplateID: row.TemplateID,
				EpochID:    row.EpochID,
			})
			if err == nil {
				claimM["epochClaimable"] = ep.Claimable
				claimM["refMode"] = ep.RefMode
			}
			claims = append(claims, claimM)
		}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{
			"wallet": strings.ToLower(wallet),
			"claims": claims,
			"dataFreshness": map[string]any{
				"lastSyncAt":       lastSync,
				"lastIndexedBlock": st.LastBlock,
			},
		})
	}
}

// UserFaucetStateHandler reads Base Sepolia faucet + stake token for a wallet.
func UserFaucetStateHandler(eth *ethops.Caller, reg *registry.Registry) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		wallet := strings.TrimSpace(r.URL.Query().Get("wallet"))
		if !strings.HasPrefix(wallet, "0x") || len(wallet) != 42 {
			http.Error(w, `{"error":"invalid wallet"}`, http.StatusBadRequest)
			return
		}
		if reg.ChainID != 84532 {
			w.Header().Set("Content-Type", "application/json")
			_ = json.NewEncoder(w).Encode(map[string]any{
				"source":  "n/a",
				"chainId": reg.ChainID,
				"note":    "faucet-state is only for Base Sepolia (84532)",
			})
			return
		}
		if eth == nil {
			http.Error(w, `{"error":"eth client unavailable"}`, http.StatusServiceUnavailable)
			return
		}
		faucet := common.HexToAddress(reg.Contracts.TokenFaucet)
		stake := common.HexToAddress(reg.Contracts.StakeToken)
		user := common.HexToAddress(wallet)
		rpcCtx, cancel := liveRPCContext(r)
		out, err := eth.GetFaucetState(rpcCtx, reg.ChainID, faucet, stake, user)
		cancel()
		if err != nil {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusBadGateway)
			_ = json.NewEncoder(w).Encode(map[string]any{"error": err.Error()})
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(out)
	}
}

