export function CompositeDemo({ reducedMotion, stepIndex }: DemoProps) {
  const s = clampStep(stepIndex, 5);
  if (s === 4) {
    return (
      <BinaryPayoutVisual
        leftLabel="Yes"
        rightLabel="No"
        winningSide="right"
