export function CorridorDemo({ reducedMotion, stepIndex }: DemoProps) {
  const s = clampStep(stepIndex, 5);
  if (s === 4) {
    return (
      <BinaryPayoutVisual
        leftLabel="Inside"
        rightLabel="Outside"
        winningSide="left"
        reducedMotion={reducedMotion}
        caption="Two-outcome pool after the path is judged"
      />
