  if (s === 5) {
    return <UseCaseHintVisual caption="Range-bound windows—not just where it closes" />;
  }
  return (
    <DemoShell
      caption={
        s === 0
          ? "Did price stay inside both rails the whole time?"
          : s === 1
            ? "Inside (never breach) vs Outside (touched a rail)"
            : s === 2
