/**
 * AML Geofencing — Jurisdiction Access Controls
 *
 * Implements Section 5 of the RetroPick AML/CFT/CPF Policy v1.0
 *
 * Hard-blocked jurisdictions (deny access):
 *   FATF Blacklisted / OFAC comprehensively sanctioned:
 *     Iran (IR), Myanmar (MM), North Korea (KP), Cuba (CU),
 *     Syria (SY), Crimea/Donetsk/Luhansk (UA — region-specific, treated as UA)
 *   Legally prohibited:
 *     Singapore (SG), Thailand (TH), Taiwan (TW), France (FR), United States (US)
 *
 * Enhanced monitoring (flag but don't hard-block — FATF grey list):
 *   Reviewed quarterly against fatf-gafi.org; list current as of April 2026.
 *
 * Policy: both IP detection AND wallet screening must pass before a user
 * may interact with the application (§5, §6 — dual-layer enforcement).
 */
import { getPublicEnv } from "@/lib/runtimeEnv"

// ── Blocked jurisdictions ─────────────────────────────────────────────────────

/** ISO 3166-1 alpha-2 country codes that are hard-blocked. */
export const BLOCKED_COUNTRY_CODES = new Set<string>([
  // FATF High-Risk / OFAC comprehensively sanctioned
  'IR', // Iran
  'MM', // Myanmar
  'KP', // North Korea (DPRK)
  'CU', // Cuba
  'SY', // Syria

  // Legally prohibited (product not authorised)
  'US', // United States — pending CFTC DCM registration
  'SG', // Singapore — Gambling Control Act 2022
  'TH', // Thailand — gambling law prohibition
  'TW', // Taiwan — election betting / prediction market prohibition
  'FR', // France — ANJ gambling prohibition (Nov 2024)
])

/** FATF Grey-list jurisdictions — enhanced monitoring, not hard-blocked. */
export const ENHANCED_MONITORING_COUNTRY_CODES = new Set<string>([
  // FATF Increased Monitoring list — April 2026
  'BF', // Burkina Faso
  'CM', // Cameroon
  'CD', // Democratic Republic of Congo
  'HT', // Haiti
  'JM', // Jamaica
  'ML', // Mali
  'MZ', // Mozambique
  'NG', // Nigeria
  'SS', // South Sudan
  'TZ', // Tanzania
  'VN', // Vietnam
  'YE', // Yemen
])

export type GeofenceResult =
  | { allowed: true;  countryCode: string; isEnhancedMonitoring: boolean }
  | { allowed: false; countryCode: string; reason: string }
  | { allowed: true;  countryCode: 'UNKNOWN'; isEnhancedMonitoring: false } // detection failed → allow

// ── Country name map for user-facing messages ─────────────────────────────────

const COUNTRY_NAMES: Record<string, string> = {
  IR: 'Iran', MM: 'Myanmar', KP: 'North Korea', CU: 'Cuba',
  SY: 'Syria', US: 'United States', SG: 'Singapore', TH: 'Thailand',
  TW: 'Taiwan', FR: 'France',
}

// ── IP geolocation ────────────────────────────────────────────────────────────

interface IpApiResponse {
  country_code: string
  country_name: string
  ip: string
}

let _cachedCountry: string | null = null
let _cacheTs = 0
const CACHE_TTL_MS = 5 * 60 * 1000 // 5 minutes

/**
 * Detects the user's country via IP geolocation.
 * Returns 'UNKNOWN' on failure (fail-open — blocked only by wallet screening).
 */
async function detectCountryCode(): Promise<string> {
  const now = Date.now()
  if (_cachedCountry && now - _cacheTs < CACHE_TTL_MS) return _cachedCountry

  try {
    // ipapi.co — free tier (1000 req/day); production should use a paid provider
    const apiKey = getPublicEnv("IP_GEOLOCATION_API_KEY")
    const url    = apiKey
      ? `https://ipapi.co/json/?key=${apiKey}`
      : 'https://ipapi.co/json/'

    const res = await fetch(url, { signal: AbortSignal.timeout(5_000) })
    if (!res.ok) return 'UNKNOWN'

    const data: IpApiResponse = await res.json()
    const cc = data.country_code?.toUpperCase() || 'UNKNOWN'
    _cachedCountry = cc
    _cacheTs       = now
    return cc
  } catch {
    return 'UNKNOWN'
  }
}

// ── Main geofencing check ─────────────────────────────────────────────────────

/**
 * Performs the geofencing check for the current user.
 *
 * When NEXT_PUBLIC_ENABLE_GEOFENCING/VITE_ENABLE_GEOFENCING is "false" (local dev), always returns allowed.
 */
export async function checkGeofence(): Promise<GeofenceResult> {
  if (getPublicEnv("ENABLE_GEOFENCING") === 'false') {
    return { allowed: true, countryCode: 'DEV', isEnhancedMonitoring: false }
  }

  const countryCode = await detectCountryCode()

  if (countryCode === 'UNKNOWN') {
    // Detection failed — allow but log; wallet screening is the fallback
    return { allowed: true, countryCode: 'UNKNOWN', isEnhancedMonitoring: false }
  }

  if (BLOCKED_COUNTRY_CODES.has(countryCode)) {
    const name = COUNTRY_NAMES[countryCode] || countryCode
    return {
      allowed: false,
      countryCode,
      reason: `RetroPick is not available in ${name}. ` +
        'Access is restricted under applicable sanctions and regulatory requirements.',
    }
  }

  return {
    allowed:              true,
    countryCode,
    isEnhancedMonitoring: ENHANCED_MONITORING_COUNTRY_CODES.has(countryCode),
  }
}

// ── Utility ───────────────────────────────────────────────────────────────────

export function isBlockedCountry(countryCode: string): boolean {
  return BLOCKED_COUNTRY_CODES.has(countryCode.toUpperCase())
}

export function isEnhancedMonitoringCountry(countryCode: string): boolean {
  return ENHANCED_MONITORING_COUNTRY_CODES.has(countryCode.toUpperCase())
}

/**
 * AML Wallet Screening — TRM Labs Integration
 *
 * Implements Section 6 of the RetroPick AML/CFT/CPF Policy v1.0
 *
 * Screening scope (per policy §6.2):
 *   - OFAC Specially Designated Nationals (SDN)
 *   - UN Consolidated Sanctions List
 *   - UAE Targeted Financial Sanctions
 *   - EU Consolidated Sanctions List
 *   - UK HM Treasury Sanctions List
 *   - TRM Labs proprietary risk DB (darknet, mixers, ransomware, scam wallets, DPRK)
 *
 * Risk threshold: wallets scoring ≥ 80 / 100 are blocked from depositing.
 * Screening logs retained 5 years (policy §10).
 *
 * Re-screening: all active depositors re-screened weekly (handled by backend worker;
 * frontend screens on every wallet connection event).
 */
import { getPublicEnv } from "@/lib/runtimeEnv"

export type RiskLevel = 'low' | 'medium' | 'high' | 'severe' | 'unknown'

export interface WalletScreeningResult {
  address:         string
  chainName:       string
  riskScore:       number      // 0–100; ≥80 = blocked
  riskLevel:       RiskLevel
  blocked:         boolean
  blockReason?:    string      // set when blocked = true
  matchedLists:    string[]    // e.g. ["OFAC SDN", "TRM Darknet"]
  screenedAt:      number      // unix ms timestamp
}

// ── Risk threshold ────────────────────────────────────────────────────────────

const BLOCK_THRESHOLD = 80 // per AML policy §6.2

function scoreToLevel(score: number): RiskLevel {
  if (score >= 80) return 'severe'
  if (score >= 60) return 'high'
  if (score >= 30) return 'medium'
  if (score >= 0)  return 'low'
  return 'unknown'
}

// ── TRM Labs API ──────────────────────────────────────────────────────────────

interface TrmEntity {
  address: string
  chain:   string
}

interface TrmRiskIndicator {
  category:    string
  categoryId:  string
  riskType:    string
  totalVolumeUsd: number
}

interface TrmEntityAssessment {
  address:          string
  chain:            string
  addressRiskScore: number
  riskIndicators:   TrmRiskIndicator[]
  entities?:        Array<{ category: string; name: string }>
  addressType?:     string
}

const TRM_API_BASE = 'https://api.trmlabs.com/public/v2'

async function callTrmApi(address: string, chain: string): Promise<TrmEntityAssessment | null> {
  const apiKey = getPublicEnv("TRM_LABS_API_KEY")
  if (!apiKey) return null

  try {
    const body: TrmEntity[] = [{ address, chain }]
    const res = await fetch(`${TRM_API_BASE}/entities/assess`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization:  `Bearer ${apiKey}`,
      },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(8_000),
    })

    if (!res.ok) return null
    const data: TrmEntityAssessment[] = await res.json()
    return data[0] ?? null
  } catch {
    return null
  }
}

/** Maps wagmi/viem chainId to the TRM Labs chain string. */
function chainIdToTrmChain(chainId: number): string {
  const MAP: Record<number, string> = {
    42161:   'arbitrum',
    421614:  'arbitrum',
    1:       'ethereum',
    8453:    'base',
    10:      'optimism',
    137:     'polygon',
    324:     'zksync_era',
    59144:   'linea',
    534352:  'scroll',
    11155111:'ethereum',
  }
  return MAP[chainId] || 'ethereum'
}

// ── Screening cache (in-memory, TTL 15 min) ───────────────────────────────────

interface CacheEntry {
  result: WalletScreeningResult
  ts:     number
}

const _cache = new Map<string, CacheEntry>()
const CACHE_TTL_MS = 15 * 60 * 1000

function cacheKey(address: string, chainId: number) {
  return `${address.toLowerCase()}-${chainId}`
}

// ── Main screening function ───────────────────────────────────────────────────

/**
 * Screens a wallet address via TRM Labs.
 *
 * When NEXT_PUBLIC_ENABLE_WALLET_SCREENING/VITE_ENABLE_WALLET_SCREENING is "false" (local dev), returns a safe result.
 * When TRM API key is not set, returns a low-risk pass (for staging without credentials).
 */
export async function screenWallet(
  address: string,
  chainId: number,
): Promise<WalletScreeningResult> {
  if (getPublicEnv("ENABLE_WALLET_SCREENING") === 'false') {
    return makeResult(address, chainId, 0, [], false)
  }

  const key = cacheKey(address, chainId)
  const cached = _cache.get(key)
  if (cached && Date.now() - cached.ts < CACHE_TTL_MS) {
    return cached.result
  }

  const chain      = chainIdToTrmChain(chainId)
  const assessment = await callTrmApi(address, chain)

  let result: WalletScreeningResult

  if (!assessment) {
    // TRM unavailable — fail-open with low risk; backend worker will re-screen
    result = makeResult(address, chainId, 0, [], false, 'TRM screening unavailable — allow pending re-screen')
  } else {
    const score       = Math.round(assessment.addressRiskScore * 100) // TRM returns 0–1
    const matchedLists = extractMatchedLists(assessment.riskIndicators)
    const blocked      = score >= BLOCK_THRESHOLD
    const blockReason  = blocked
      ? `Wallet risk score ${score}/100 exceeds threshold. Matched: ${matchedLists.join(', ') || 'proprietary risk database'}.`
      : undefined

    result = makeResult(address, chainId, score, matchedLists, blocked, blockReason)
  }

  _cache.set(key, { result, ts: Date.now() })
  return result
}

function makeResult(
  address:      string,
  chainId:      number,
  riskScore:    number,
  matchedLists: string[],
  blocked:      boolean,
  blockReason?: string,
): WalletScreeningResult {
  return {
    address,
    chainName:   chainIdToTrmChain(chainId),
    riskScore,
    riskLevel:   scoreToLevel(riskScore),
    blocked,
    blockReason,
    matchedLists,
    screenedAt:  Date.now(),
  }
}

function extractMatchedLists(indicators: TrmRiskIndicator[]): string[] {
  const SANCTION_CATEGORIES: Record<string, string> = {
    'sanctions':           'OFAC SDN / Sanctions List',
    'terrorist_financing': 'Terrorist Financing',
    'darknet_market':      'Darknet Market',
    'mixer':               'Mixer / Tumbler',
    'ransomware':          'Ransomware',
    'scam':                'Scam / Fraud',
    'stolen_funds':        'Stolen Funds',
  }

  const found = new Set<string>()
  for (const ind of indicators) {
    const label = SANCTION_CATEGORIES[ind.categoryId] || ind.category
    if (label) found.add(label)
  }
  return Array.from(found)
}

/** Evict a single address from the cache (e.g., after a CNMR/PNMR match is cleared). */
export function evictScreeningCache(address: string, chainId: number) {
  _cache.delete(cacheKey(address, chainId))
}

