  Olympics: 'Sports',
  Cricket: 'Sports',
  Esports: 'Sports',
  CS2: 'Sports',
  'Dota 2': 'Sports',
  'League of Legends': 'Sports',

  // Space / Science
  Science: 'Space',
  Space: 'Space',
  SpaceX: 'Space',
  NASA: 'Space',

  // AI
  AI: 'AI',
  'Artificial Intelligence': 'AI',
