}

@layer utilities {
  .no-scrollbar::-webkit-scrollbar {
    display: none;
  }

  .no-scrollbar {
    -ms-overflow-style: none;
    scrollbar-width: none;
  }

  .glass-panel {
    background: hsl(var(--glass));
    backdrop-filter: blur(12px);
    border: 1px solid hsl(var(--glass-border));
  }

  .glass-panel:hover {
    background: hsl(var(--glass-hover));
