"use client";

import { useLiveOps } from "@/components/LiveOpsContext";

/**
 * Surfaces operator-critical lag between indexer head and last live RPC refresh.
 */
export function IndexerLiveLag({
  indexedBlock,
}: {
  indexedBlock: number | null | undefined;
}) {
  const { liveGlobal } = useLiveOps();
  const live = liveGlobal?.blockNumber;
  if (indexedBlock == null || live == null) return null;
  const lag = Number(live) - indexedBlock;
  const warn = lag > 20 || lag < 0;

  return (
    <div
      className={
        warn
          ? "border-b border-amber-900/40 bg-amber-950/30 px-4 py-2 text-xs text-amber-100"
          : "border-b border-[color:var(--color-mainBorder)] bg-[color:var(--color-secondaryBg)] px-4 py-1.5 text-xs text-[color:var(--color-placeholderText)]"
      }
    >
      <span className="font-medium text-[color:var(--color-primaryText)]">Head check:</span> indexer{" "}
      <span className="font-mono">{indexedBlock}</span> vs live RPC{" "}
      <span className="font-mono">{live}</span>
      {lag >= 0 ? (
        <>
          {" "}
          (Δ <span className="font-mono">{lag}</span> blocks)
        </>
      ) : (
        <span> — refresh live after indexer catches up</span>
      )}
      {warn ? (
        <span className="ml-2 text-amber-200/90">
          Large lag or RPC behind indexer — verify before acting.
        </span>
      ) : null}
    </div>
  );
}

files.apps/ops/src/components/LiveOpsContext.t:
"use client";

import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
} from "react";

import { fetchLiveGlobal, type LiveEnvelope, type LiveGlobalData } from "@/lib/api";

type LiveCtx = {
  liveGlobal: LiveEnvelope<LiveGlobalData> | null;
  liveError: string | null;
  loadingLive: boolean;
  refreshLiveGlobal: () => Promise<void>;
};

const Ctx = createContext<LiveCtx | null>(null);

export function LiveOpsProvider({ children }: { children: React.ReactNode }) {
  const [liveGlobal, setLiveGlobal] = useState<LiveEnvelope<LiveGlobalData> | null>(
    null,
  );
  const [liveError, setLiveError] = useState<string | null>(null);
  const [loadingLive, setLoadingLive] = useState(false);

  const refreshLiveGlobal = useCallback(async () => {
    setLoadingLive(true);
    setLiveError(null);
    try {
      const g = await fetchLiveGlobal();
      setLiveGlobal(g);
    } catch (e) {
      setLiveError(e instanceof Error ? e.message : "live fetch failed");
      setLiveGlobal(null);
    } finally {
      setLoadingLive(false);
    }
  }, []);

  const v = useMemo(
    () => ({
      liveGlobal,
      liveError,
      loadingLive,
      refreshLiveGlobal,
    }),
    [liveGlobal, liveError, loadingLive, refreshLiveGlobal],
  );

  return <Ctx.Provider value={v}>{children}</Ctx.Provider>;
}

export function useLiveOps() {
  const x = useContext(Ctx);
  if (!x) {
    throw new Error("useLiveOps outside LiveOpsProvider");
  }
  return x;
}

