  updatedAt: string | null;
  lastIndexedBlock: number;
  winningOutcomeMask?: number;
};

export type KeeperScheduleRow = {
  id: number;
  action: string;
  status: string;
  scheduledAt?: string;
  windowEndAt?: string;
  createdAt?: string;
  templateId?: string;
