@import "tailwindcss";
@import "tw-animate-css";
@import "./themes/light.css";
@import "./themes/dark.css";
@import "./themes/authBgPattern.css";
@import "./overrides/calendar.css";
@import "./overrides/datepicker.css";
@import "./overrides/lightbox.css";

/* Custom breakpoints */
@theme {
  --breakpoint-xsm: 30rem; /* 480px */
  --breakpoint-1xl: 87.5rem; /* 1400px */
  --breakpoint-3xl: 109.375rem; /* 1750px */
  --breakpoint-5xl: 125rem; /* 2000px */
}

html,
body {
  padding: 0;
  margin: 0;
  scroll-behavior: smooth;
  scrollbar-gutter: stable;
  background-color: var(--color-secondaryBg);
}

html {
  scroll-padding-top: 100px;
}

@layer base {
  a {
    color: inherit;
    text-decoration: none;
  }
}

* {
  box-sizing: border-box;
}

button {
  cursor: pointer;
}

/* Font switching via class toggle */
body {
  font-family: var(--font-outfit), sans-serif;
  color: var(--color-primaryText);
}

body.font-alternative {
  font-family: var(--font-open-sans), sans-serif;
}

/* Prevent Radix UI Select from hiding page scrollbar */
[data-scroll-locked][data-scroll-locked] {
  overflow-y: auto !important;
  margin-right: 0 !important;
}

/* Main loader animation */

@keyframes loader {
  to {
    opacity: 0.1;
    transform: translateY(-1rem);
  }
}

.animate-loader {
  animation-name: loader;
  animation-duration: 0.6s;
  animation-iteration-count: infinite;
  animation-direction: alternate;
}

@layer utilities {
  .animation-delay-200 {
    animation-delay: 0.2s;
  }
  .animation-delay-400 {
    animation-delay: 0.4s;
  }
}

.circle {
  @apply w-4 h-4 my-12 mx-1 bg-loaderCircleBg rounded-full;
}

/* Submenu expand/collapse animation */
.CollapsibleContent {
  overflow: hidden;
}

.CollapsibleContent[data-state="open"] {
  animation: submenuSlideDown 150ms ease-out;
}

.CollapsibleContent[data-state="closed"] {
  animation: submenuSlideUp 150ms ease-out;
}

@keyframes submenuSlideDown {
  from {
    height: 0;
  }
  to {
    height: var(--radix-collapsible-content-height);
  }
}

@keyframes submenuSlideUp {
  from {
    height: var(--radix-collapsible-content-height);
  }
  to {
    height: 0;
  }
}

/* Navbar dropdown enter animation (translateZ(0) prevents sub-pixel shift from GPU layer switch) */
@keyframes navbarDropdownEnter {
  from {
    opacity: 0;
    transform: translateZ(0) scale(0.95) translateY(-8px);
  }
  to {
    opacity: 1;
    transform: translateZ(0) scale(1) translateY(0);
  }
}

.animate-navbar-dropdown {
  animation: navbarDropdownEnter 150ms ease-out forwards;
  transform: translateZ(0);
}

/* Font color for axis ticks in Recharts charts */
.recharts-cartesian-axis-tick-value tspan,
.recharts-polar-angle-axis-tick-value tspan,
.recharts-cartesian-axis-tick text {
  fill: var(--color-chartAxisText);
}

/* Global accessible focus styles - in @layer base so Tailwind utilities
   (e.g. focus-visible:outline-offset-[-1px]) can override outline-offset per element */
@layer base {
  *:focus {
    outline: none;
  }

  *:focus-visible {
    outline: 2px solid var(--color-focusVisibleBorder);
    outline-offset: 2px;
  }
}

/* Disable focus ring inside dropdowns/menus - use background highlight instead (higher specificity) */
[role="menu"] :focus-visible,
[role="listbox"] :focus-visible,
[data-radix-collection-item]:focus-visible {
  outline: none;
}

/* Focus ring on tabs */
[role="tablist"] > [data-radix-collection-item]:focus-visible {
  outline: 2px solid var(--color-focusVisibleBorder);
  outline-offset: 2px;
}

/* Override Tailwind v4 transition utilities to exclude outline-color.
   Tailwind v4 includes outline-color in transition/transition-colors by default,
   which causes focus-visible outline to fade-in instead of appearing instantly. */
.transition-transform-forced {
  transition: transform 200ms ease !important;
}

/* Dialog container should never show focus ring (focus trap fallback target) */
[role="dialog"]:focus-visible {
  outline: none;
}

/* Hide native password reveal button (Edge/Chromium) - custom toggle is used instead */
input::-ms-reveal,
input::-ms-clear {
  display: none;
}

/* Inputs - subtle border focus instead of colored ring (consistent with Material, Chakra UI) */
input:focus-visible,
textarea:focus-visible {
  outline: none;
}

input:focus,
textarea:focus {
  border-color: var(--color-inputBorderFocus);
}

/* Overwrite autofill styles for inputs to ensure consistent appearance */
:root {
  --primary-text-color: var(--color-primaryText);
}

input:-webkit-autofill,
input:-webkit-autofill:hover,
input:-webkit-autofill:focus,
input:-webkit-autofill:active {
  -webkit-background-clip: text;
  box-shadow: inset 0 0 20px 20px rgb(255, 255, 255, 0.03);
  -webkit-text-fill-color: var(--primary-text-color) !important;
  @apply !bg-inputBg;
  transition: background-color 5000s ease-in-out 0s;
}

/* Class needed to display different colors for the content spinner */
.contentSpinner {
  @apply fill-primaryText;
}

.menuItemIcon svg {
  @apply w-5 h-5 3xl:w-5.5 3xl:h-5.5;
}

.menuItemLogo svg {
  @apply w-9 h-9 xl:w-8 xl:h-8 1xl:w-9 1xl:h-9 3xl:w-[2.45rem] 3xl:h-[2.45rem];
  transform: rotate(0deg);
}

/* Custom Scrollbar */
:root {
  --scrollbar-thumb: var(--color-scrollbarThumb);
  --scrollbar-bg: var(--color-scrollbarBg);
}

.dark {
  --scrollbar-thumb: var(--color-scrollbarThumb);
  --scrollbar-bg: var(--color-scrollbarBg);
}

* {
  scrollbar-color: var(--scrollbar-thumb) var(--scrollbar-bg);
  scrollbar-width: thin;
}

/* Fallback for older WebKit browsers without standard scrollbar-width support */
@supports not (scrollbar-width: thin) {
  ::-webkit-scrollbar {
    width: 6px;
    height: 6px;
  }

  ::-webkit-scrollbar-track {
    background: var(--scrollbar-bg);
  }

  ::-webkit-scrollbar-thumb {
    background: var(--scrollbar-thumb);
    border-radius: 3px;
  }

  ::-webkit-scrollbar-button {
    display: none;
  }
}

.alternativeScrollbar {
  --scrollbar-bg: var(--color-primaryBg);
}

/* Prevent stretching customer photo vertically */
.customersTable img {
  min-width: 40px;
  min-height: 40px;
}

/* Override Tailwind v4 transition/transition-colors to exclude outline-color,
   preventing brief flash of white border on elements during keyboard navigation */
@layer utilities {
  .transition {
    transition-property:
      color,
      background-color,
      border-color,
      text-decoration-color,
      fill,
      stroke,
      --tw-gradient-from,
      --tw-gradient-via,
      --tw-gradient-to,
      opacity,
      box-shadow,
      transform,
      translate,
      scale,
      rotate,
      filter,
      -webkit-backdrop-filter,
      backdrop-filter,
      display,
      content-visibility,
      overlay,
      pointer-events;
    transition-timing-function: var(--default-transition-timing-function);
    transition-duration: var(--default-transition-duration);
  }

  .transition-colors {
    transition-property:
      color, background-color, border-color, text-decoration-color, fill,
      stroke, --tw-gradient-from, --tw-gradient-via, --tw-gradient-to;
    transition-timing-function: var(--default-transition-timing-function);
    transition-duration: var(--default-transition-duration);
  }
}

